package com.governai.decision;
import com.governai.organization.RiskLevel; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import tools.jackson.databind.JsonNode; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="decision_request") public class DecisionRequest { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="organization_id") private UUID organizationId; @Column(name="requested_by") private UUID requestedBy; @Column(nullable=false,columnDefinition="text") private String question; @Column(columnDefinition="text") private String purpose; @Column(length=255) private String provider; @Column(name="data_type",length=255) private String dataType; @JdbcTypeCode(SqlTypes.JSON) @Column(name="additional_context",columnDefinition="jsonb") private JsonNode additionalContext; @Column(length=100) private String jurisdiction; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(name="risk_level",columnDefinition="risk_level_enum") private RiskLevel riskLevel; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="decision_status_enum") private DecisionStatus status=DecisionStatus.DRAFT; @Column(name="human_review_required",nullable=false) private boolean humanReviewRequired; @Column(name="assigned_reviewer") private UUID assignedReviewer; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; @PrePersist void create(){var now=OffsetDateTime.now();if(createdAt==null)createdAt=now;if(updatedAt==null)updatedAt=now;if(status==null)status=DecisionStatus.DRAFT;}@PreUpdate void update(){updatedAt=OffsetDateTime.now();} public UUID getId(){return id;} public UUID getOrganizationId(){return organizationId;} public void setOrganizationId(UUID v){organizationId=v;} public UUID getRequestedBy(){return requestedBy;} public void setRequestedBy(UUID v){requestedBy=v;} public String getQuestion(){return question;} public void setQuestion(String v){question=v;} public String getPurpose(){return purpose;} public void setPurpose(String v){purpose=v;} public String getProvider(){return provider;} public void setProvider(String v){provider=v;} public String getDataType(){return dataType;} public void setDataType(String v){dataType=v;} public JsonNode getAdditionalContext(){return additionalContext;} public void setAdditionalContext(JsonNode v){additionalContext=v;} public String getJurisdiction(){return jurisdiction;} public void setJurisdiction(String v){jurisdiction=v;} public RiskLevel getRiskLevel(){return riskLevel;} public void setRiskLevel(RiskLevel v){riskLevel=v;} public DecisionStatus getStatus(){return status;} public void setStatus(DecisionStatus v){status=v;} public boolean isHumanReviewRequired(){return humanReviewRequired;} public void setHumanReviewRequired(boolean v){humanReviewRequired=v;} public UUID getAssignedReviewer(){return assignedReviewer;} public void setAssignedReviewer(UUID v){assignedReviewer=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;} }
